package app.metrolife;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;

class CommunityTests {
 @TempDir Path dir;ObjectMapper mapper=new ObjectMapper();GameService g;Content content;String token,friend;long now=System.currentTimeMillis();
 JsonNode j(String text)throws Exception{return mapper.readTree(text);}ObjectNode sim(String t){return g.sim(g.session(t,true));}ObjectNode world(){return g.world(g.session(token,true));}
 @BeforeEach void setup()throws Exception{content=new Content(mapper);g=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),content,mapper);g.time=()->now;token=g.guest(null,j("{\"username\":\"First Friend\"}")).token();g.createWorld(token,j("{\"name\":\"Our town\",\"mode\":\"private\"}"));g.setup(token,j("{\"city\":\"atl\",\"neighborhood\":\"midtown\",\"aspiration\":\"founder\"}"));friend=g.guest(null,j("{\"username\":\"Second Friend\"}")).token();g.joinWorld(friend,g.object().put("code",world().path("code").asText()));g.setup(friend,j("{\"city\":\"atl\",\"neighborhood\":\"midtown\",\"aspiration\":\"founder\"}"));sim(token).put("loc","centennial");sim(friend).put("loc","centennial");g.community.online.put(world().path("id").asText()+":"+sim(friend).path("userId").asText(),now);}
 JsonNode social(String kind,int amount){return g.social(token,g.object().put("targetId",sim(friend).path("userId").asText()).put("kind",kind).put("amount",amount));}
 @Test void socialsApplyBothEffectsCashLedgerAndCooldownOnce(){double social=sim(friend).path("needs").path("social").asDouble();social("wave",0);assertEquals(social+3,sim(friend).path("needs").path("social").asDouble());assertEquals(429,assertThrows(ApiException.class,()->social("wave",0)).status);now+=3000;social("hangout",0);assertTrue(sim(friend).path("needs").path("social").asDouble()>99);now+=3000;double a=sim(token).path("cash").asDouble(),b=sim(friend).path("cash").asDouble();social("gift",25);assertEquals(a-25,sim(token).path("cash").asDouble());assertEquals(b+25,sim(friend).path("cash").asDouble());assertEquals(25,sim(token).path("moneyToday").path("spent").asInt());assertEquals(25,sim(friend).path("moneyToday").path("income").asInt());assertFalse(g.getSim(token).path("sim").has("_socialAt"));assertFalse(g.getSim(token).path("sim").has("_lastSocial"));}
 @Test void forgedRemoteOfflineBusyAndFractionalGiftsFail()throws Exception{assertEquals(404,assertThrows(ApiException.class,()->g.social(token,j("{\"targetId\":\"forged\",\"kind\":\"gift\",\"amount\":5}"))).status);sim(friend).put("loc","fox");assertEquals(409,assertThrows(ApiException.class,()->social("wave",0)).status);sim(friend).put("loc","centennial");sim(friend).put("busyUntil",now+5000);assertEquals(409,assertThrows(ApiException.class,()->social("wave",0)).status);sim(friend).putNull("busyUntil");assertEquals(400,assertThrows(ApiException.class,()->g.social(token,g.object().put("targetId",sim(friend).path("userId").asText()).put("kind","gift").put("amount",2.5))).status);assertEquals(400,assertThrows(ApiException.class,()->social("gift",-5)).status);g.community.online.clear();assertEquals(409,assertThrows(ApiException.class,()->social("wave",0)).status);String id=sim(friend).path("userId").asText();g.createWorld(token,j("{\"name\":\"Other town\",\"mode\":\"solo\"}"));g.setup(token,j("{\"city\":\"atl\",\"neighborhood\":\"midtown\",\"aspiration\":\"founder\"}"));assertEquals(404,assertThrows(ApiException.class,()->g.social(token,g.object().put("targetId",id).put("kind","wave"))).status);}
 @Test void chatIsBoundedCityWorldScopedValidatedAndPersistent()throws Exception{g.say(token,j("{\"city\":\"atl\",\"text\":\"Hello neighbours\"}"));assertEquals(429,assertThrows(ApiException.class,()->g.say(token,j("{\"city\":\"atl\",\"text\":\"Again\"}"))).status);now+=1500;assertEquals(400,assertThrows(ApiException.class,()->g.say(token,j("{\"city\":\"atl\",\"text\":\"😀\"}"))).status);assertEquals(403,assertThrows(ApiException.class,()->g.say(token,j("{\"city\":\"nyc\",\"text\":\"Not here\"}"))).status);for(int i=0;i<55;i++){now+=1500;g.say(token,g.object().put("city","atl").put("text","Message "+i));}assertEquals(50,g.chat(friend,"atl").path("messages").size());assertEquals(0,g.chat(friend,"nyc").path("messages").size());GameService restored=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),content,mapper);restored.time=()->now;assertEquals(50,restored.chat(friend,"atl").path("messages").size());g.createWorld(token,j("{\"name\":\"Elsewhere\",\"mode\":\"solo\"}"));assertEquals(0,g.chat(token,"atl").path("messages").size());}
 @Test void privateHomesDoNotCountAsSharedSocialPlaces(){sim(token).put("loc","home");sim(friend).put("loc","home");assertEquals("Meet at a public place first",assertThrows(ApiException.class,()->social("wave",0)).getMessage());}
 @Test void residentsHaveDistinctNamesAndVisibleProgressAndReserveTheirNames()throws Exception{
  g.createWorld(token,j("{\"name\":\"Naming review\",\"mode\":\"solo\"}"));g.players(token,"atl");var rows=g.community.residents().path(world().path("id").asText());var names=new java.util.HashSet<String>();var lastNames=new java.util.HashSet<String>();
  for(JsonNode n:rows){assertTrue(names.add(n.path("username").asText()));lastNames.add(n.path("username").asText().split(" ")[1]);assertTrue(n.path("level").asInt()>1);}
  assertEquals(120,names.size());assertTrue(lastNames.size()>=35);String reserved=rows.elements().next().path("username").asText();assertEquals(409,assertThrows(ApiException.class,()->g.guest(null,g.object().put("username",reserved))).status);
  for(int i=0;i<20;i++)assertFalse(names.contains(g.guest(null,g.object()).user().path("username").asText()));
  g.store.save();GameService restored=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),content,mapper);assertEquals(names,java.util.stream.StreamSupport.stream(restored.community.residents().path(world().path("id").asText()).spliterator(),false).map(n->n.path("username").asText()).collect(java.util.stream.Collectors.toSet()));
 }
 @Test void residentCountsMovementVotingPurchaseSparsityAndRestart()throws Exception{JsonNode first=g.players(token,"atl");assertEquals(22,first.path("players").size());assertEquals(60,g.community.residents().path(world().path("id").asText()).size());sim(token).withObject("skills").withObject("charisma").put("level",2);g.mayorAction(token,"run",j("{\"city\":\"atl\",\"slogan\":\"More music in parks\"}"));String initial=g.community.residents().path(world().path("id").asText()).toString();now+=180000;g.community.tick();assertNotEquals(initial,g.community.residents().path(world().path("id").asText()).toString());assertEquals(3,g.mayor(token,"atl").path("candidates").get(0).path("votes").asInt());assertEquals(2,g.plots(token,"atl").path("ads").size());assertTrue(g.chat(token,"atl").path("messages").size()<=1);g.store.save();GameService restored=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),content,mapper);restored.time=()->now;assertEquals(22,restored.players(token,"atl").path("players").size());g.createWorld(token,j("{\"name\":\"Quiet life\",\"mode\":\"solo\"}"));assertEquals(40,g.players(token,"nyc").path("players").size());assertEquals(10,g.players(null,"bay").path("players").size());}
}
